  },
  suv: {
    name: "SUV",
    heightRange: "6'2\" - 6'4\"",
    length: "22 - 24 feet"
  },
  truck: {
    name: "Truck",
    heightRange: "6'5\" - 6'7\"",
    length: "24 - 26 feet"
  },
  van: {
    name: "Van",
    heightRange: "6'8\" and up",
    length: "26+ feet"
  }
};

function getCarSize(height) {
  for (let size in carSizes) {
    if (height >= carSizes[size].heightRange) {
      return size;
    }
  }
  return "Van"; // If the customer's height is greater than or equal to 6'8", recommend a van.

To achieve this, you can create a function that takes a sentence as input and returns a new sentence with the order of adjectives reversed. Here's a simple approach using JavaScript:

```javascript
function reverseAdjectives(sentence) {
  // Split the sentence into words
  const words = sentence.split(" ");

  // Reverse the order of adjectives
  const adjectives = words.filter((word) => word === word.toLowerCase());
  adjectives.reverse();

  // Reconstruct the sentence with reversed adjectives
  const result = adjectives.join(" ") + " " + words.filter((word) => !word === word.toLowerCase()).join(" ");

  return result;
}

// Test the function
const originalSentence = "Beautiful green trees are in the park";
const reversedSentence = reverseAdjectives(originalSentence);
console.log(reversedSentence); // Output: "Green beautiful trees are in the park"
```

This function first splits the sentence into individual words. Then, it filters out all words that are not adjectives (case-insensitive comparison). Finally, it reverses the order of adjectives and reconstructs the sentence by combining the adjectives and non-adjective words separately. The resulting sentence has the adjectives in reverse order.

