class Matrix {
public:
    Matrix(int rows, int columns) : rows_(rows), columns_(columns) {
        data_ = new double[rows * columns];
    }

    ~Matrix() {
        delete[] data_;
    }

    void setValue(int row, int column, double value) {
        data_[row * columns + column] = value;
    }

    double getValue(int row, int column) const {
        return data_[row * columns + column];
    }

    void render(QPainter& painter, int x, int y, int width, int height) const {
        painter.setRenderHint(QPainter::Antialiasing);
        painter.translate(x, y);
        painter.scale(width / rows_, height / columns_);

        for (int i = 0; i < rows_; i++) {
            for (int j = 0; j < columns_; j++) {
                painter.drawRect(j * width / columns_, i * height / rows_, width / columns_, height / rows_);
            }
        }
    }

    void zoom(double factor) {
        scale_ *= factor;
    }

private:
    int rows_;
    int columns_;
    double* data_;
    double scale_ = 1.0;
};

