    // Calculate the most common colors and products
    let mostCommonColors = data.colorPreferences.mostCommon()
    let mostCommonProducts = data.productReviews.mostCommon()

    // Determine the user's favorite color and product
    guard let favoriteColor = mostCommonColors.first else { return "I couldn't determine your favorite color." }
