echo json_encode($sorted_set); // Output: [{"name":"John","address":"123 Main St","age":30},{"name":"Jane","address":"456 Elm St","age":25},{"name":"Bob","address":"789 Oak St","age":35}]

$sorted_set = smart_sort_array($set, 'desc'); // Sort in descending order
