Here's a React component using Hooks to convert between different temperature units:

```jsx
import React, { useState } from 'react';

const TemperatureConverter = () => {
  const [temperature, setTemperature] = useState(0);
  const [fromUnit, setFromUnit] = useState('C');
  const [toUnit, setToUnit] = useState('F');

  const handleConvert = () => {
    if (fromUnit === 'C') {
      const convertedTemp = (temperature * 1.8) + 32;
      setTemperature(convertedTemp);
    } else {
      const convertedTemp = (temperature - 32) * 5 / 9;
      setTemperature(convertedTemp);
    }
  };

  return (
    <div>
      <h2>Temperature Converter</h2>
      <label htmlFor="temperature">Enter temperature:</label>
      <input
        type="number"
        id="temperature"
        value={temperature}
        onChange={e => setTemperature(parseFloat(e.target.value))}
      />
      <select value={fromUnit} onChange={e => setFromUnit(e.target.value)}>
        <option value="C">Celsius</option>
        <option value="F">Fahrenheit</option>
      </select>
      <select value={toUnit} onChange={e => setToUnit(e.target.value)}>
        <option value="C">Celsius</option>
        <option value="F">Fahrenheit</option>
      </select>
      <button onClick={handleConvert}>Convert</button>
      <p>Result: {temperature} {toUnit}</p>
    </div>
  );
};

export default TemperatureConverter;
```

