To achieve this task, you'll need to use a combination of Python libraries such as NLTK for natural language processing, re for regular expressions, and collections for counting items. Here's an example script that identifies the most common non-silent vowel and consonant combinations in a given text:

```python
import nltk
from nltk.corpus import stopwords
from nltk.tokenize import word_tokenize
import re
from collections import Counter

def is_vowel(char):
    return char.lower() in 'aeiou'

def is_consonant(char):
    return not is_vowel(char)

def extract_combinations(text):
    combinations = []
    words = word_tokenize(text)
    for word in words:
        for i in range(len(word)):
            vowel = is_vowel(word[i])
            consonant = is_consonant(word[i])
            if vowel and consonant:
                combinations.append((word[i], word[i+1]))
    return combinations

def count_combinations(combinations):
    count = Counter(combinations)
    return count

def find_most_common(count):
    return count.most_common(10)

def main():
    # Replace this with your actual text
    text = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed non risus. Suspendisse lectus tortor, dignissim sed, adipiscing nec, ultricies sed, dolor. Cras mattis consectetur purus, sed tincidunt magna aliquet non."

    combinations = extract_combinations(text)
    count = count_combinations(combinations)
    most_common = find_most_common(count)

    print("Most common non-silent vowel and consonant combinations:")
    for combination, count in most_common:
        print(f"{combination}: {count}")

