Here's a simple C function that converts an array of command-line arguments (`argv`) to a null-terminated string (`c_str`):

```c
#include <stdio.h>
#include <stdlib.h>

char *convert_argv_to_c_str(int argc, char *argv[]) {
    char *c_str = malloc((argc + 1) * sizeof(char)); // allocate memory for the c_str
    if (!c_str) {
        return NULL;
    }

    int i = 0;
    while (i < argc) {
        strcat(c_str, argv[i]);
        strcat(c_str, " ");
        i++;
    }

    // remove the last space character
    c_str[strlen(c_str) - 1] = '\0';

    return c_str;
}

int main() {
    int argc = 3;
    char *argv[] = {"hello", "world", "!"};

    char *c_str = convert_argv_to_c_str(argc, argv);
    if (c_str) {
        printf("Converted c_str: %s\n", c_str);
        free(c_str);
    } else {
        printf("Error allocating memory for c_str.\n");
    }

    return 0;
}
```

This function takes two arguments: `argc` and `argv`. It allocates memory for a null-terminated string, then iterates through the `argv` array, concatenating each argument with a space character. Finally, it removes the last space character and returns the resulting c_str.

In the `main` function, we create an example `argv` array and call the `convert_argv_to_c_str` function to convert it to a c_str. We then print the converted c_str and free the memory allocated for it.

