import boto3
import argparse
import json

def parse_args():
    parser = argparse.ArgumentParser(description="Retries failed step functions workflows")
    parser.add_argument("--region", type=str, default="us-west-2", help="AWS region")
    parser.add_argument("--state-machine-arn", type=str, required=True, help="ARN of the state machine")
    parser.add_argument("--max-retries", type=int, default=10, help="Maximum number of retries")
    return parser.parse_args()

def get_failed_workflows(client, state_machine_arn):
    response = client.list_runs(
        stateMachineArn=state_machine_arn,
        statusFilter=[
            "Failed",
            "Stopped",
        ],
    )
    failed_workflows = []
    for run in response["runs"]:
        if run["status"] == "Failed" or run["status"] == "Stopped":
            failed_workflows.append(run)
    return failed_workflows

def retry_workflow(client, state_machine_arn, run_id, max_retries):
    response = client.start_run(
        stateMachineArn=state_machine_arn,
        input={
            "input": failed_workflow["input"],
            "name": f"{failed_workflow['name']} (Retry {retry})",
        },
    )
    retry += 1
    if retry >= max_retries:
        print(f"Failed to retry workflow {run_id}: Max retries reached")
    else:
        print(f"Retrying workflow {run_id}: Retry {retry}")

if __name__ == "__main__":
    args = parse_args()

    client = boto3.client("stepfunctions", region_name=args.region)

    failed_workflows = get_failed_workflows

