import re
from decimal import Decimal

def num_to_words(num, lang='en'):
    if lang not in ['en', 'fr', 'es', 'de']:
        raise ValueError("Invalid language")

    if isinstance(num, str):
        # Handle scientific notation
        match = re.match(r'(\d+)\.?(\d*)e(\d+)', num)
        if match:
            num = Decimal(match.group(1)) * 10**int(match.group(3))
            if match.group(2):
                num += Decimal(match.group(2)) / 10**int(match.group(3))

    if num < 0:
        return f"negative {num_to_words(-num, lang)}"

    words = []
    if num == 0:
        return "zero"

    if num >= 1000000000:
        words.append(num_to_words(num // 1000000000, lang))
        words.append("billion")
        num %= 1000000000

    if num >= 100000000:
        words.append(num_to_words(num // 100000000, lang))
        words.append("million")
        num %= 100000000

    if num >= 1000000:
        words.append(num_to_words(num // 1000000, lang))
        words.append("hundred thousand")
        num %= 1000000

    if num >= 1000:
        words.append(num_to_words(num // 1000, lang))
        words.append("thousand")
        num %= 1000

    if num >= 100:
        words.append(num_to_words(num // 100, lang))

