Here's a function that sorts an array of integers in ascending order using the bubble sort algorithm:

```javascript
function bubbleSort(arr) {
  const n = arr.length;

  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - i - 1; j++) {
      if (arr[j] > arr[j + 1]) {
        // Swap elements
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
      }
    }
  }

  return arr;
}

const inputArray = [3, 7, 2, 1, 6];
const sortedArray = bubbleSort(inputArray);
console.log(sortedArray); // Output: [1, 2, 3, 6, 7]
```

