Here's the `redis.js` file with the `RedisClient` class and the exported instance `redisClient`:

```javascript
// inside the folder utils
const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: 'localhost',
      port: 6379,
      maxRetries: 5,
      retryStrategy: (times) => {
        return times * 100;
      },
    });

    this.client.on('error', (error) => {
      console.error(`Redis error: ${error}`);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (error) {
      return false;
    }
  }

  async get(key) {
    const value = await this.client.get(key);
    return value;
  }

  async set(key, value, duration) {
    await this.client.setex(key, duration, value);
  }

  async del(key) {
    await this.client.del(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code defines the `RedisClient` class with its constructor and four methods: `isAlive`, `get`, `set`, and `del`. It also exports an instance of the `RedisClient` class called `redisClient`. Make sure to install the `ioredis` package if you haven't already:

```bash
npm install ioredis
```

