# Import the ActiveDirectory module
Import-Module ActiveDirectory

# Define the folder path to start the search from
$folderPath = "C:\Path\To\Your\Folder"

# Function to check if an SID exists only in the SIDHistory of any user or group in the domain
function CheckSIDInSIDHistory($sid) {
    $domain = (Get-ADDomain).Name
    $users = Get-ADUser -Filter {(ObjectCategory -eq "person")} -Properties SID -SearchBase "DC=$domain,DC=com"
    $groups = Get-ADGroup -Filter {(ObjectCategory -eq "group")} -Properties SID -SearchBase "DC=$domain,DC=com"

    foreach ($user in $users) {
        if ($user.SID -eq $sid) {
            return $true
        }
    }

    foreach ($group in $groups) {
        if ($group.SID -eq $sid) {
            return $true
        }
    }

    return $false
}

